changeSet.sql:
DO $$ DECLARE conflicts text; BEGIN SELECT string_agg(format('workspace %s, native id %s, monitors %s', g.workspace_id, g.native_id, g.ids), '; ' ORDER BY g.workspace_id, g.native_id) INTO conflicts FROM (SELECT m.workspace_id, m.native_id, array_agg(m.id ORDER BY m.id) AS ids FROM repository_to_monitor m LEFT JOIN review_scope_repository s ON s.workspace_id = m.workspace_id AND s.repository_monitor_id = m.id WHERE m.native_id IS NOT NULL GROUP BY m.workspace_id, m.native_id HAVING count(*) > 1 AND (count(DISTINCT m.name_with_owner) > 1 OR count(DISTINCT m.generated_paths) > 1 OR count(DISTINCT s.base_branches) > 1)) g; IF conflicts IS NOT NULL THEN RAISE EXCEPTION 'Duplicate repository monitors disagree on their path, generated paths or review branches: %. Restore the pre-upgrade backup and report these monitor ids.', conflicts; END IF; END $$;
-- 2. The lowest id survives. When only a duplicate has a review scope row, that row moves to the survivor. -- When the survivor already has a row, step 1 proved the branches are equal, so nothing is written. INSERT INTO review_scope_repository (workspace_id, repository_monitor_id, base_branches) SELECT DISTINCT ON (d.workspace_id, d.survivor) d.workspace_id, d.survivor, s.base_branches FROM (SELECT id, workspace_id, min(id) OVER (PARTITION BY workspace_id, native_id) AS survivor FROM repository_to_monitor WHERE native_id IS NOT NULL) d JOIN review_scope_repository s ON s.workspace_id = d.workspace_id AND s.repository_monitor_id = d.id WHERE d.id <> d.survivor ORDER BY d.workspace_id, d.survivor, d.id ON CONFLICT (repository_monitor_id, workspace_id) DO NOTHING;
-- 3. Remove the duplicates. The survivor keeps its own cursors, timestamps, backfill marks and errors as one -- set; no field takes another row's value. Their review scope rows (already copied or equal) cascade. DELETE FROM repository_to_monitor m USING (SELECT workspace_id, native_id, min(id) AS survivor FROM repository_to_monitor WHERE native_id IS NOT NULL GROUP BY workspace_id, native_id HAVING count(*) > 1) g WHERE m.workspace_id = g.workspace_id AND m.native_id = g.native_id AND m.id <> g.survivor;
